#### Phase 2: Implement Structured Logging in Application

**Step 2.1: Add Structured Logging Library (C# Example with Serilog)**

Install Serilog packages:

```bash
dotnet add package Serilog
dotnet add package Serilog.Sinks.File
dotnet add package Serilog.Formatting.Compact
dotnet add package Serilog.Enrichers.Environment
dotnet add package Serilog.Enrichers.Thread
```

Configure Serilog in `Program.cs`:

```csharp
using Serilog;
using Serilog.Formatting.Compact;

Log.Logger = new LoggerConfiguration()
    .Enrich.FromLogContext()
    .Enrich.WithProperty("service_name", "claims-service")
    .Enrich.WithProperty("environment", Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT"))
    .Enrich.WithProperty("version", "1.2.3")
    .MinimumLevel.Information()
    .WriteTo.Console(new CompactJsonFormatter())
    .WriteTo.File(
        new CompactJsonFormatter(),
        "/var/log/claims-service/app.json",
        rollingInterval: RollingInterval.Day,
        retainedFileCountLimit: 7
    )
    .CreateLogger();

var builder = WebApplication.CreateBuilder(args);
builder.Host.UseSerilog();
```

**Step 2.2: Create Correlation ID Middleware**

Add middleware to extract or generate correlation ID:

```csharp
public class CorrelationIdMiddleware
{
    private readonly RequestDelegate _next;
    private const string CorrelationIdHeader = "X-Correlation-ID";

    public CorrelationIdMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Extract or generate correlation ID
        var correlationId = context.Request.Headers[CorrelationIdHeader].FirstOrDefault()
            ?? $"CORR-{DateTime.UtcNow:yyyy-MM-dd}-{Guid.NewGuid().ToString("N")[..8].ToUpper()}";

        // Store in context for downstream access
        context.Items["CorrelationId"] = correlationId;

        // Add to response header for client tracking
        context.Response.Headers.Add(CorrelationIdHeader, correlationId);

        // Push to Serilog LogContext (automatically included in all logs)
        using (LogContext.PushProperty("correlation_id", correlationId))
        {
            await _next(context);
        }
    }
}

// Register middleware
app.UseMiddleware<CorrelationIdMiddleware>();
```

**Step 2.3: Log Structured Events with Contextual Data**

Use structured logging with named properties:

```csharp
public class ClaimsController : ControllerBase
{
    private readonly ILogger<ClaimsController> _logger;

    [HttpPost("claims")]
    public async Task<IActionResult> SubmitClaim([FromBody] ClaimRequest request)
    {
        // Log request received with structured data
        _logger.LogInformation(
            "Claim submission received from provider {ProviderId} for member {MemberId} with claim type {ClaimType}",
            request.ProviderId,
            request.MemberId,
            request.ClaimType
        );

        var stopwatch = Stopwatch.StartNew();

        try
        {
            // Validate claim
            var validationResult = await _claimValidator.ValidateAsync(request);

            if (!validationResult.IsValid)
            {
                // Log validation failure with error details
                _logger.LogWarning(
                    "Claim validation failed for claim {ClaimId} with {ErrorCount} errors: {Errors}",
                    request.ClaimId,
                    validationResult.Errors.Count,
                    validationResult.Errors.Select(e => e.ErrorMessage)
                );

                return BadRequest(validationResult.Errors);
            }

            // Process claim
            var result = await _claimProcessor.ProcessAsync(request);

            stopwatch.Stop();

            // Log successful processing with metrics
            _logger.LogInformation(
                "Claim {ClaimId} processed successfully in {DurationMs}ms with status {ClaimStatus}",
                request.ClaimId,
                stopwatch.ElapsedMilliseconds,
                result.Status
            );

            return Ok(result);
        }
        catch (DatabaseException ex)
        {
            stopwatch.Stop();

            // Log error with exception details
            _logger.LogError(
                ex,
                "Database error processing claim {ClaimId} after {DurationMs}ms: {ErrorMessage}",
                request.ClaimId,
                stopwatch.ElapsedMilliseconds,
                ex.Message
            );

            return StatusCode(500, "Database error occurred");
        }
    }
}
```

