Log with structured fields using SLF4J with Logback:

```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

public class EligibilityService {
    private static final Logger logger = LoggerFactory.getLogger(EligibilityService.class);

    public EligibilityResponse checkEligibility(String memberId, String correlationId) {
        // Add correlation ID to MDC (automatically included in all logs)
        MDC.put("correlation_id", correlationId);

        try {
            logger.info("Eligibility check started for member {}", memberId);

            // Business logic...

            logger.info("Eligibility check completed for member {} with status {}",
                memberId, response.getStatus());

            return response;
        } finally {
            MDC.clear();
        }
    }
}
```

**Node.js with Winston:**

Install Winston:

```bash
npm install winston
```

Configure Winston in `logger.js`:

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: {
    service_name: 'fhir-api',
    environment: process.env.NODE_ENV || 'dev',
    version: '3.0.1'
  },
  transports: [
    new winston.transports.File({
      filename: '/var/log/fhir-api/app.json',
      maxsize: 100 * 1024 * 1024, // 100MB
      maxFiles: 7
    })
  ]
});

module.exports = logger;
```

Use in application:

```javascript
const logger = require('./logger');
const { v4: uuidv4 } = require('uuid');

// Middleware to add correlation ID
app.use((req, res, next) => {
  const correlationId = req.headers['x-correlation-id'] ||
    `CORR-${new Date().toISOString().split('T')[0]}-${uuidv4().slice(0, 8).toUpperCase()}`;

  req.correlationId = correlationId;
  res.setHeader('X-Correlation-ID', correlationId);
  next();
});

// Controller with structured logging
app.get('/Patient/:id', async (req, res) => {
  const startTime = Date.now();

  logger.info('FHIR Patient request received', {
    correlation_id: req.correlationId,
    patient_id: req.params.id,
    http_method: req.method,
    http_path: req.path,
    source_ip: req.ip
  });

  try {
    const patient = await patientService.getPatient(req.params.id);
    const duration = Date.now() - startTime;

    logger.info('FHIR Patient request completed', {
      correlation_id: req.correlationId,
      patient_id: req.params.id,
      http_status: 200,
      duration_ms: duration
    });

    res.json(patient);
  } catch (error) {
    const duration = Date.now() - startTime;

    logger.error('FHIR Patient request failed', {
      correlation_id: req.correlationId,
      patient_id: req.params.id,
      error_message: error.message,
      error_type: error.constructor.name,
      stack_trace: error.stack,
      http_status: 500,
      duration_ms: duration
    });

    res.status(500).json({ error: 'Internal server error' });
  }
});
```

**Python with structlog:**

Install structlog:

```bash
pip install structlog
```

Configure in `logging_config.py`:

```python
import structlog
import logging

logging.basicConfig(
    format="%(message)s",
    level=logging.INFO,
    handlers=[
        logging.FileHandler("/var/log/pharmacy-service/app.json"),
        logging.StreamHandler()
    ]
)

structlog.configure(
    processors=[
        structlog.contextvars.merge_contextvars,
        structlog.processors.add_log_level,
        structlog.processors.TimeStamper(fmt="iso"),
        structlog.processors.JSONRenderer()
    ],
    wrapper_class=structlog.make_filtering_bound_logger(logging.INFO),
    context_class=dict,
    logger_factory=structlog.PrintLoggerFactory(),
)

logger = structlog.get_logger()

# Add service metadata
structlog.contextvars.bind_contextvars(
    service_name="pharmacy-service",
    environment="prod",
    version="1.5.2"
)
```

Use in application:

```python
from logging_config import logger
import structlog
import uuid
from datetime import datetime

@app.before_request
def before_request():
    correlation_id = request.headers.get('X-Correlation-ID')
    if not correlation_id:
        date_str = datetime.utcnow().strftime('%Y-%m-%d')
        unique_id = str(uuid.uuid4())[:8].upper()
        correlation_id = f"CORR-{date_str}-{unique_id}"

    structlog.contextvars.bind_contextvars(correlation_id=correlation_id)
    g.start_time = time.time()

@app.route('/prescriptions/<member_id>', methods=['GET'])
def get_prescriptions(member_id):
    logger.info("prescription_request_received",
                member_id=member_id,
                http_method=request.method,
                http_path=request.path)

    try:
        prescriptions = prescription_service.get_by_member(member_id)
        duration_ms = int((time.time() - g.start_time) * 1000)

        logger.info("prescription_request_completed",
                    member_id=member_id,
                    prescription_count=len(prescriptions),
                    duration_ms=duration_ms,
                    http_status=200)

        return jsonify(prescriptions), 200

    except DatabaseError as e:
        duration_ms = int((time.time() - g.start_time) * 1000)

        logger.error("prescription_request_failed",
                     member_id=member_id,
                     error_message=str(e),
                     error_type=type(e).__name__,
                     duration_ms=duration_ms,
                     http_status=500)

        return jsonify({"error": "Database error"}), 500
```

